// 独立条件控制同意必要来源门：真实Interaction接口的有限组件，未登记完整World。
#include "resident/domains/family/family_legacy.hpp"
#include "resident/storage/common_checkpoint.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {
using V=BoundaryValue;int checks=0;
// 保留首个失败，后续普通矩阵不在本组件运行。
void check(bool value,const char* why){++checks;if(!value)throw std::runtime_error(why);}
// 同一Common角色与原会话节点，接受/撤回各自有不同的本人语义来源。
struct Fixture {
    std::shared_ptr<CommonCatalog> shared=std::make_shared<CommonCatalog>();CommonState seed;FamilyState family;InteractionCatalog interaction;InteractionState state;LegacyControlConsentCatalog catalog;
    Fixture(){family.founder_actor_id="former";
        seed.identity.world_id[0]=8;seed.identity.execution_epoch=2;seed.identity.revision=5;seed.identity.tick=20;seed.metadata.scenario_id="scene";seed.metadata.player_actor_id="former";seed.next_instance_id=9;
        shared->actor_ids={"former","next"};shared->places.insert("home",{"home","town",{}});RoleDefinition role;role.id="contact";role.initial_actor="next";role.place_id="home";shared->roles.insert(role.id,role);seed.roles.insert(role.id,{"next",true,{}});
        for(const auto* name:{"former","next"}){ActorRecord actor;actor.id=name;actor.alive=true;actor.available=true;actor.hp=100;actor.birth_tick=-20000;actor.location=SettlementLocation{"town","home"};seed.actors.insert(name,actor);}
        AdultAdoptionFact adopted;adopted.agreement.adopter_actor_id="former";adopted.agreement.adoptee_actor_id="next";adopted.agreement.accepted_tick=1;family.facts.insert("family:1",adopted);family.children.insert("next","family:1");seed.facts.insert("family:1",{"family:1","family_adult_adoption","family",{}});
        DialogueDefinition talk;talk.id="dialogue";talk.context_role="contact";talk.entry="yes";for(const auto* id:{"yes","withdraw","old_retirement"}){DialogueNode node;node.id=id;node.kind="say";node.speaker="$provider";talk.nodes.push_back(node);}interaction.dialogues.push_back(talk);interaction.common=shared;
        InteractionSession session;session.actor_id="former";session.id="interaction:2";session.dialogue_id="dialogue";session.node_id="yes";session.phase="say";session.context={"home","next","contact"};state.interactions.push_back(session);
        LegacyControlConsentDefinition d;d.id="conditional";d.predecessor_actor_id="former";d.successor_actor_id="next";d.dialogue_id="dialogue";d.accept_node_id="yes";d.revoke_node_id="withdraw";catalog.enabled=true;catalog.definitions.insert(d.id,d);
    }
};
}

// 风险组件仅注入具名来源读口，不声称原军事World已自然产出死亡。
int main(){try{
    Fixture f;CommonStore common(f.seed,f.shared);FamilyDeathState deaths;FamilyLegacyState legacy;
    FamilyDeathOriginRead death_read=[&](const StableId& id)->Outcome<std::optional<FamilyDeathOrigin>>{if(id=="former"&&!common.actor(id)->alive)return {true,FamilyDeathOrigin{id,"military:10","battle:4",21},{}};return {true,{}, {}};};
    InteractionAccess access;access.battle_occupied=[](const StableId&){return false;};access.resolve_location=[&](const StableId& id){return common.actor(id)->location;};access.role=[&](const StableId& id)->std::optional<RoleAssignmentView>{const auto* row=common.state().roles.find(id);if(!row)return {};return RoleAssignmentView{row->actor_id,row->enabled};};
    auto quote=preview_legacy_control_decision(common,f.family,f.state,f.interaction,access,f.catalog,"former","next","conditional","accept");check(quote.ok,"consent source missing");
    auto accepted=record_family_legacy_decision(common,f.family,deaths,death_read,f.state,f.interaction,access,f.catalog,legacy,quote.value);if(!accepted.ok)std::cerr<<accepted.error.original.code<<'\n';check(accepted.ok&&legacy.consents.size()==1,"consent ledger refused original decision");
    const auto saved=encode_common_state(common.state());auto repeated=record_family_legacy_decision(common,f.family,deaths,death_read,f.state,f.interaction,access,f.catalog,legacy,quote.value);check(repeated.ok&&repeated.value==accepted.value&&compare_boundary(saved,encode_common_state(common.state())).exact(),"accept replay generated a second fact");
    auto revoked_common=common.state();auto revoked_legacy=legacy;CommonStore revoke_store(revoked_common,f.shared);f.state.interactions.front().node_id="withdraw";auto revoke_quote=preview_legacy_control_decision(revoke_store,f.family,f.state,f.interaction,access,f.catalog,"former","next","conditional","revoke");check(revoke_quote.ok,"withdrawal source missing");auto revoked=record_family_legacy_decision(revoke_store,f.family,deaths,death_read,f.state,f.interaction,access,f.catalog,revoked_legacy,revoke_quote.value,accepted.value);check(revoked.ok&&revoked_legacy.revocations.size()==1,"own explicit withdrawal missing");f.state.interactions.front().node_id="yes";
    common.state().identity.tick=21;auto* original=common.state().actors.find("former");original->alive=false;original->available=false;original->hp=0;auto casualty=common.next_id("military");check(casualty.ok&&casualty.value=="military:10","fixture cause order changed");check(common.append_fact({casualty.value,"military_casualties","military"}).ok,"cause head missing");auto died=record_family_death(common,deaths,death_read,"former");check(died.ok,"actual typed death source refused");
    FamilyLegacyPlayableRead playable=[&](const StableId& actor,Integer tick,const StableId& boundary){if(!boundary.empty()){auto original_player=family_player_before_fact_with_legacy(common,f.family,legacy,tick,boundary);if(!original_player.ok||original_player.value!="former")return common_failure("CandidateLegacyBorrowStale");}return actor=="next"&&tick==21&&(boundary.empty()||common.state().facts.find(boundary))?common_success():common_failure("FixturePlayableMismatch");};
    check(!preview_family_legacy_activation(common,f.family,deaths,death_read,*f.shared,f.interaction,f.catalog,legacy,{},accepted.value).ok,"missing playable proof accepted");auto activation=preview_family_legacy_activation(common,f.family,deaths,death_read,*f.shared,f.interaction,f.catalog,legacy,playable,accepted.value);if(!activation.ok)std::cerr<<activation.error.original.code<<'\n';check(activation.ok,"eligible agreed successor refused");
    const auto before=encode_common_state(common.state()),before_legacy=encode_family_legacy(legacy);
    FamilyLegacyPlayableRead fail_after_control=[&](const StableId& actor,Integer tick,const StableId& boundary){if(!boundary.empty())return common_failure("InjectedHistoricalPlayableFailure");return playable(actor,tick,boundary);};
    auto failed=activate_family_legacy_control(common,f.family,deaths,death_read,*f.shared,f.interaction,f.catalog,legacy,fail_after_control,activation.value);check(!failed.ok&&failed.error.original.code=="InjectedHistoricalPlayableFailure","post-control failure not reached");check(compare_boundary(before,encode_common_state(common.state())).exact()&&compare_boundary(before_legacy,encode_family_legacy(legacy)).exact(),"late failure left player/fact/ID/ledger changed");
    auto changed=activate_family_legacy_control(common,f.family,deaths,death_read,*f.shared,f.interaction,f.catalog,legacy,playable,activation.value);if(!changed.ok)std::cerr<<changed.error.original.code<<'\n';check(changed.ok&&common.state().metadata.player_actor_id=="next"&&legacy.activations.size()==1,"control activation failed");const auto after=encode_common_state(common.state());for(const auto& row:*before.as<V::Dict>())if(row.first!="player_actor_id"&&row.first!="facts"&&row.first!="next_instance_id")check(after.find(row.first)&&compare_boundary(row.second,*after.find(row.first)).exact(),"zero-asset control changed other Common state");
    auto previous=family_player_before_fact_with_legacy(common,f.family,legacy,21,changed.value);check(previous.ok&&previous.value=="former","new player backfilled old fact source");check(!activate_family_legacy_control(common,f.family,deaths,death_read,*f.shared,f.interaction,f.catalog,legacy,playable,activation.value).ok,"old control quote replayed");
    for(auto state:{legacy,revoked_legacy}){const auto encoded=encode_family_legacy(state);auto json=decode_family_legacy(encoded);check(json.ok&&compare_boundary(encoded,encode_family_legacy(json.value)).exact(),"ledger JSON cold changed");CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);check(visit_family_legacy_checkpoint(writer,json.value).ok&&writer.finish().ok,"ledger typed write failed");const auto& input=bytes;CodecVisitor reader(input);FamilyLegacyState cold;check(visit_family_legacy_checkpoint(reader,cold).ok&&reader.finish().ok&&compare_boundary(encoded,encode_family_legacy(cold)).exact(),"ledger typed cold changed");bytes.pop_back();const auto& truncated=bytes;CodecVisitor broken(truncated);FamilyLegacyState bad;check(!visit_family_legacy_checkpoint(broken,bad).ok||!broken.finish().ok,"truncated legacy segment accepted");}
    auto corrupt=encode_family_legacy(legacy);corrupt.as<V::Dict>()->emplace_back("consents",V{V::Dict{}});check(!decode_family_legacy(corrupt).ok,"duplicate ledger root accepted");corrupt=encode_family_legacy(legacy);auto* decision=corrupt.find("consents")->find(accepted.value)->find("source");decision->as<V::Dict>()->emplace_back("decision",V{StableId{"revoke"}});check(!decode_family_legacy(corrupt).ok,"nested contradictory decision accepted");auto disabled=f.catalog;disabled.enabled=false;check(!validate_family_legacy(common,f.family,deaths,death_read,*f.shared,f.interaction,disabled,legacy,playable).ok,"disabled legacy state accepted");auto orphan=legacy;orphan.activations={};check(!validate_family_legacy(common,f.family,deaths,death_read,*f.shared,f.interaction,f.catalog,orphan,playable).ok,"orphan activated header accepted");
    std::cout<<"FAMILY_LEGACY "<<checks<<" checks 0 failures\n";return 0;
}catch(const std::exception& error){std::cerr<<"FAMILY_LEGACY "<<checks<<" checks 1 failure: "<<error.what()<<'\n';return 1;}}
